#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1'000'000'007;
const int N = 200'000;
long long fact[N + 1], inv_fact[N + 1];

long long power(long long b, long long e) {   // 빠른 거듭제곱
    long long r = 1;
    b %= MOD;
    while (e > 0) {
        if (e & 1) r = r * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return r;
}

long long nCr(int n, int r) {
    if (r < 0 || r > n) return 0;              // 범위 밖 인덱스를 읽지 않게
    return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD;
}

int main() {
    fact[0] = 1;
    for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;   // long long 배열이라 넘치지 않아요
    inv_fact[N] = power(fact[N], MOD - 2);                        // 페르마 소정리(MOD 가 소수)
    for (int i = N; i >= 1; i--) inv_fact[i - 1] = inv_fact[i] * i % MOD;

    cout << "C(5, 2) = " << nCr(5, 2) << '\n';
    cout << "C(3, 5) = " << nCr(3, 5) << '\n';
    cout << "C(200000, 100000) % MOD = " << nCr(200000, 100000) << '\n';

    long long a = nCr(10, 3), b = nCr(10, 4);
    cout << "C(10,3) - C(10,4) = " << ((a - b) % MOD + MOD) % MOD << '\n';   // 음수 나머지 보정
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    // 파스칼 삼각형: MOD 가 소수가 아니어도, n 이 수천 이하일 때
    const int M = 10;
    vector<vector<int>> C(M + 1, vector<int>(M + 1, 0));
    for (int n = 0; n <= M; n++) {
        C[n][0] = 1;
        for (int r = 1; r <= n; r++) C[n][r] = (C[n - 1][r - 1] + C[n - 1][r]) % 1000;
    }
    cout << "C(10, r) % 1000 =";
    for (int r = 0; r <= M; r++) cout << ' ' << C[M][r];
    cout << '\n';

    // 나머지 없이 정확한 값: 곱하고 바로 나누면 매 단계가 정수예요
    auto exact = [](long long n, long long r) {
        long long res = 1;
        for (long long i = 1; i <= r; i++) res = res * (n - r + i) / i;
        return res;
    };
    cout << "격자 경로 " << exact(3 + 4, 3) << '\n';
    cout << "중복조합 " << exact(7 + 3 - 1, 3 - 1) << '\n';
    cout << "C(60, 30) " << exact(60, 30) << '\n';
    return 0;
}
